import pytest

from src.api.routes.items import (
    favorite_item,
    get_item,
    list_favorite_items,
    list_items,
    unfavorite_item,
)
from src.api.routes.users import get_user


@pytest.fixture(autouse=True)
def _reset_favorites():
    snapshot = {}
    for user_id in (1, 2):
        user = get_user(user_id)
        if user is not None:
            snapshot[user_id] = list(user.favorite_item_ids)
            user.favorite_item_ids.clear()
    yield
    for user_id, fav in snapshot.items():
        user = get_user(user_id)
        if user is not None:
            user.favorite_item_ids[:] = fav


def test_list_items_omits_archived_items_by_default():
    items = list_items()
    assert all(not item["archived"] for item in items)


def test_get_item_returns_matching_item():
    assert get_item(1)["name"] == "Notebook"


def test_favorite_item_records_favorite():
    result = favorite_item(1, 1)
    assert result == {"user_id": 1, "item_id": 1, "favorited": True}
    assert get_user(1).favorite_item_ids == [1]


def test_favorite_item_is_idempotent():
    favorite_item(1, 1)
    favorite_item(1, 1)
    assert get_user(1).favorite_item_ids == [1]


def test_favorite_non_owned_item_fails():
    with pytest.raises(ValueError):
        favorite_item(1, 3)
    assert get_user(1).favorite_item_ids == []


def test_unfavorite_removes_favorite():
    favorite_item(1, 1)
    result = unfavorite_item(1, 1)
    assert result == {"user_id": 1, "item_id": 1, "favorited": False}
    assert get_user(1).favorite_item_ids == []


def test_unfavorite_not_currently_favorited_is_idempotent():
    result = unfavorite_item(1, 1)
    assert result == {"user_id": 1, "item_id": 1, "favorited": False}
    assert get_user(1).favorite_item_ids == []


def test_list_favorite_items_returns_item_dicts():
    favorite_item(1, 1)
    favorite_item(1, 2)
    favorites = list_favorite_items(1)
    assert [f["id"] for f in favorites] == [1, 2]
    assert favorites[0]["name"] == "Notebook"


def test_list_favorite_items_empty_when_none_favorited():
    assert list_favorite_items(1) == []

